/** Age on 1 September of the season's first year (e.g. '03-04' -> 1 Sep 2003). */
export function ageInSeason(born: string | undefined, season: string): number | null {
  if (!born) return null;
  const yy = parseInt(season.slice(0, 2), 10);
  const start = new Date(Date.UTC(yy >= 90 ? 1900 + yy : 2000 + yy, 8, 1));
  const b = new Date(born + 'T00:00:00Z');
  let age = start.getUTCFullYear() - b.getUTCFullYear();
  if (start.getUTCMonth() < b.getUTCMonth() || (start.getUTCMonth() === b.getUTCMonth() && start.getUTCDate() < b.getUTCDate())) age--;
  return age;
}
